package("fmt")
    set_homepage("https://fmt.dev")
    set_license("MIT")
    set_urls("$(projectdir)/third_party/sources/fmt-$(version).zip")
    add_versions("10.2.1", "312151a2d13c8327f5c9c586ac6cf7cddc1658e8f53edae0ec56509c8fa516c9")
    add_deps("cmake")
    on_install(function (package)
        import("package.tools.cmake").install(package, {"-DFMT_TEST=OFF", "-DFMT_DOC=OFF", "-DBUILD_SHARED_LIBS=OFF"})
    end)
